declare(strict_types=1);
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;
require __DIR__ . '/../../../vendor/autoload.php';
[, $sourceRoot] = $argv + [null, null];
if (!is_string($sourceRoot) || !is_dir($sourceRoot)) throw new InvalidArgumentException('Usage: generate-files.php SOURCE_ROOT (major/path layout; sources pinned in files-sources.json)');
$pins = json_decode(file_get_contents(__DIR__ . '/files-sources.json'), true, 512, JSON_THROW_ON_ERROR);
foreach ($pins as $major => $sources) {
    $tree = $sourceRoot . '/' . $major;
    foreach ($sources as $path => $pin) {
        if (!is_file($tree . '/' . $path) || hash_file('sha256', $tree . '/' . $path) !== $pin['sha256']) throw new RuntimeException('Pinned Files source mismatch: ' . $major . '/' . $path);
    }
    $destination = __DIR__ . '/' . $major . '.php';
    $fixture = require $destination;
    $parser = new SourceParser($tree);
    foreach (['OCA\\Files\\Event\\LoadAdditionalScriptsEvent', 'OCP\\AppFramework\\Http\\DataResponse', 'OCP\\FilesMetadata\\Exceptions\\FilesMetadataNotFoundException', 'OCP\\SystemTag\\TagAlreadyExistsException'] as $class) {
        $fixture['classes'][$class] = $parser->surface($class) ?? throw new RuntimeException('Missing pinned class: ' . $class);
    }
    $header = explode('return [', file_get_contents($destination), 2)[0];
    if (!str_contains($header, 'generate-files.php')) $header .= '// Files additions generated by generate-files.php; official source URLs and SHA256 in files-sources.json.\n';
    $header = str_replace('files-sources.json.\\n', "files-sources.json.\n", $header);
    FixtureFile::write($destination, $header, $fixture);
    echo 'Updated Files API additions for Nextcloud ' . $major . PHP_EOL;
}
